import './share.scss';
import { useContext, useState } from 'react';
import { AuthContext } from '../../context/authContext';
import axios from 'axios';

const Share = () => {
  const { currentUser, accessToken } = useContext(AuthContext);
  const [desc, setDesc] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!desc.trim()) {
      console.log('Share: No description provided');
      return;
    }

    try {
      console.log('Share: Posting with desc:', desc);
      const headers = { Authorization: `Bearer ${accessToken}` };
      await axios.post(
        'http://localhost:5000/api/posts',
        { desc },
        { headers }
      );
      console.log('Share: Post created successfully');
      setDesc('');
      window.location.reload(); // Refresh to show new post
    } catch (err) {
      console.error('Share: Error creating post:', err.message, err.response?.data);
    }
  };

  if (!currentUser) {
    return <div>Please login to share a post.</div>;
  }

  return (
    <div className="share">
      <div className="container">
        <div className="top">
          <img
            src={currentUser.profilePicture || '/default-avatar.png'}
            alt=""
            className="profile-img"
          />
          <textarea
            placeholder={`What's on your mind, ${currentUser.name}?`}
            value={desc}
            onChange={(e) => setDesc(e.target.value)}
          />
        </div>
        <hr />
        <div className="bottom">
          <button onClick={handleSubmit} className="share-btn">
            Share
          </button>
        </div>
      </div>
    </div>
  );
};

export default Share;
